import{_ as t,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const c=JSON.parse('{"title":"Impersonate","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/customers/impersonate/index.md","filePath":"api/graphql-api/admin/customers/impersonate/index.md","lastUpdated":1787725411000}'),i={name:"api/graphql-api/admin/customers/impersonate/index.md"};function n(r,e,d,h,m,l){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="impersonate" tabindex="-1">Impersonate <a class="header-anchor" href="#impersonate" aria-label="Permalink to &quot;Impersonate&quot;">​</a></h1><p>The Impersonate menu is the API equivalent of the admin datagrid&#39;s <strong>&quot;Login as Customer&quot;</strong> action — it lets an admin act as a customer to reproduce an issue, check what the customer sees, or place an order in their shoes.</p><h2 id="how-login-as-customer-works-headlessly" tabindex="-1">How &quot;Login as Customer&quot; works headlessly <a class="header-anchor" href="#how-login-as-customer-works-headlessly" aria-label="Permalink to &quot;How &quot;Login as Customer&quot; works headlessly&quot;">​</a></h2><p>In the admin panel, &quot;Login as Customer&quot; logs the admin into the storefront as that customer through a browser session. That session-based flow doesn&#39;t translate to a stateless API, so the API does the headless equivalent: it <strong>issues a short-lived customer token</strong>. The admin uses that token as the customer&#39;s Bearer token to call the storefront API (<code>/api/shop/*</code>) as the customer.</p><p>So &quot;login as customer&quot; becomes &quot;get a customer token&quot;.</p><h2 id="token-semantics" tabindex="-1">Token semantics <a class="header-anchor" href="#token-semantics" aria-label="Permalink to &quot;Token semantics&quot;">​</a></h2><ul><li>The issued token is <strong>short-lived — it expires one hour after issue</strong>.</li><li>It is tagged with the issuing admin&#39;s id for audit, so impersonation is traceable.</li><li>The response returns the token plus the customer&#39;s id, email, and name, the issuing admin id, and the expiry time.</li></ul><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>token</code></td><td>The customer Bearer token to use against the storefront API.</td></tr><tr><td><code>customerId</code> / <code>customerEmail</code> / <code>customerName</code></td><td>Who the token acts as.</td></tr><tr><td><code>impersonatedByAdminId</code></td><td>The admin who issued it (audit).</td></tr><tr><td><code>expiresAt</code></td><td>When the token stops working (one hour from issue).</td></tr></tbody></table><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./create.html">Issue Impersonation Token</a></td><td><code>createAdminCustomerImpersonate</code> mutation</td></tr></tbody></table><p>Permission: <code>customers.customers.edit</code>.</p>',12)]))}const p=t(i,[["render",n]]);export{c as __pageData,p as default};
